You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\subsection{Notation and conventions}\label{subsec:notation}
We use bold font for tuples of data associated with product groups, for example, we write $\group{G}_{\ituple{n}} = \prod_{i = 1}^m \GL_{n_i}$ where $\ituple{n} = (n_1,
\dots,n_m) \in \bbN^m$.

We denote by $\bbN$ the set of nonnegative integers and by~$[n]$ the $n$-element set $\{1, \dots, n\}$.

All vector spaces are complex vector spaces.
By a \emph{group} we mean a linear algebraic group over $\bbC$, unless stated otherwise.

Unless stated otherwise, $\overline{\mathcal{X}}$ denotes Zariski closure of a set~$\mathcal{X}$.

\subsection{Algebraic groups, representations, invariants}\label{subsec:algebraic groups}
\begin{definition}[General linear group]
    For a vector space $V$, the \emph{general linear group} $\GL(V)$ is the group of invertible linear operators on $V$.
    We define~$\GL_n = \GL(\bbC^n)$.

    The general linear group $\GL(V)$ is an \emph{affine algebraic group}: it can be identified with the affine variety
    \[\GL(V) = \{(A, c) \mid c \cdot \det A = 1\} \subset \mathrm{Hom}(V,V) \oplus \bbC.\]
    In this form the multiplication and inversion in $\GL(V)$ are given by polynomial maps:
    $(A_1, c_1) \cdot (A_2, c_2) = (A_1 A_2, c_1 c_2)$ and $(A, c)^{-1} = (c \cdot \operatorname{adj} A, \det A)$.
\end{definition}

\begin{definition}[Linear algebraic group]
    A \emph{linear algebraic group} is a subgroup of some general linear group which is also an closed subvariety.
    A \emph{subgroup} of a linear algebraic group $\group{G}$ is a subgroup which is also a closed subvariety.
    A \emph{homomorphism} of algebraic groups is a group homomorphism which is also a morphism of affine varieties.
\end{definition}

\begin{definition}[Representation]
    A \emph{representation} of a group $\group{G}$ is a vector space~$X$ equipped with a homomorphism $\rho\colon \group{G} \to \GL(X)$.
    We write $\group{g} x$ for $\rho(\group{g})x$ if $\rho$ is clear from the context.
    We will often use the notation $\rep{X}{\group{G}}$ to refer to a representation of~$\group{G}$ on~$X$ (the map~$\rho$ is left implicit in the notation).

    A \emph{subrepresentation} of $X$ is a vector subspace~$Y \subset X$ such that $\rho(\group{g}) Y \subseteq Y$ for every $\group{g} \in \group{G}$.
    A representation is \emph{irreducible} if it has no nontrivial subrepresentations.

    If $X$ and $Y$ are representaions of $\group{G}$, then a linear $\alpha \colon X \to Y$ is \emph{equivariant} if $\alpha(\group{g} x) = \group{g} \alpha(x)$ for all $x \in X$ and $\group{g} \in \group{G}$.
\end{definition}

\begin{definition}[Orbit, equivalence, closure equivalence]\label{def:orbit and equivalence}
    Let $X$ be a representation of $\group{G}$ and $x \in X$.
    The \emph{orbit} of $x$ is \[\group{G} x = \{ \group{g} x \mid \group{g} \in G\}.\]
    We say that two elements $x, y \in X$ are \emph{equivalent (under the action of $\group{G}$)}
    if there exists $\group{g} \in \group{G}$ such that $y = \group{g} x$ or, equivalently, if the orbits $\group{G} x$ and $\group{G} y$ coincide.
    We say that $x$ and $y$ are \emph{closure equivalent} if they have intersecting orbit closures, that is, if~$\overline{\group{G} x} \cap \overline{\group{G} y} \neq \varnothing$.
    We denote equivalence by $\sim_{\group{G}}$ and closure equivalence by $\approx_{\group{G}}$, omitting the subscript if the group is clear from the context.
\end{definition}

\begin{definition}[Invariant]
    Let $X$ be a representation of $\group{G}$.
    A polynomial $F \in \bbC[X]$ is \emph{invariant} under the action of $\group{G}$ if $F(\group{g} \cdot x) = F(x)$ for all $x \in X$ and $\group{g} \in \group{G}$.
    Invariant polynomials form a subalgebra $\bbC[X]^{\group{G}}$ of $\bbC[X]$ called the \emph{invariant algebra}.
\end{definition}

\begin{definition}
    An algebraic group $\group{G}$ is \emph{(linearly) reductive} if every representation of $\group{G}$ can be decomposed into a direct sum of irreducible representations.
\end{definition}

\begin{definition}\label{def:sep}
    Let $X$ be a representation of reductive group $\group{G}$.
    A set of invariants $\Gamma \subset \bbC[X]^{\group{G}}$ is a \emph{separating set} if for every $x, y\in X$ we have $x \approx_{\group{G}} y$ if and only if $F(x) = F(y)$ for all $F \in \Gamma$.
\end{definition}

\subsection{Sequences of representations and orbit closure intersection problems}\label{subsec:orbit-closure-intersection-problems}
\begin{definition}[$p$-sequence]\label{def:p seq}
    A \emph{polynomially bounded sequence of representations}, or a \emph{$p$-sequence of representations}, is given by a sequence of groups $\group{G}_n$, a sequence of representations~$\rho_n \colon \group{G}_n \to \GL(X_n)$ on vector spaces~$X_n$ such that the dimension $\dim X_n$ is polynomially bounded as a function of~$n\in\bbN$, and a choice of basis in every vector space $X_n$.
    As with representations, we often write $\rep{X_n}{\group{G}_n}$ for such a $p$-sequence of representations, leaving the homomorphisms $\rho_n$ and bases implicit.

    A \emph{multivariate $p$-sequence of representations} is defined analogously but with~$\ituple{n} = (n_1, \dots, n_m) \in \bbN^m$ a tuple of parameters.
\end{definition}

\begin{definition}[Orbit closure intersection problem]
    Let~$\rep{X_n}{\group{G}_n}$ be a $p$-sequence of representations.
    Denote by~$X_n(\bbF)$ the set of elements in $X_n$ coordinates of which (in the chosen basis) lie in the subfield $\bbF$.
    The \emph{orbit closure intersection problem} $\OCI\rep{X_n}{\group{G}_n}$ is the following decision problem:

    \begin{quote}
      {\emph{Given $n$ (encoded in unary) and two elements\linebreak $x, y \in X_n(\bbF)$ (encoded as tuples of elements of~$\bbF$, which are the coordinates in the chosen basis), decide if~$x \approx_{\group{G}_n} y$.}}
    \end{quote}
\end{definition}

\subsection{Reductions between representations and orbit closure intersection problems}\label{subsec:reductions}
\begin{definition}[Efficient algebraic reduction]\label{def:algebraic reduction}
    Let $\rep{X_n}{\group{G}_n}$ and $\rep{Y_n}{\group{H}_n}$ be two $p$-sequences of representations.
    An \emph{algebraic reduction} from $\rep{X_n}{\group{G}_n}$ to $\rep{Y_n}{\group{H}_n}$ is a sequence of polynomial maps $\alpha_n \colon X_n \to Y_{q(n)}$ for some function $q\colon \bbN \to \bbN$ such that the following holds for all $n\in \bbN$, $x,y \in X_n$:
    \begin{align*}
        x \approx_{\group{G}_n} y
        \quad\Leftrightarrow\quad
        \alpha_n(x) \approx_{\group{H}_{q(n)}} \alpha_n(y).
    \end{align*}
    Such a reduction is called \emph{efficient} if~$q$ is polynomially bounded, the maps~$\alpha_n$ are defined over $\bbF$, and the functions~$q$ and~$(n, x) \mapsto \alpha_n(x)$ for $x \in X_n(\bbF)$ are efficiently computable (with $n$ given in unary and elements of $X_n$ and $Y_{q(n)}$ encoded as tuples of coordinates in the chosen bases).
    Analogous definitions are made for multivariate $p$-sequences.
\end{definition}

\subsection{Criteria for reductions}\label{subsec:criterion}
\begin{definition}
Consider groups $\group{G}$ and $\group{H}$ acting on vector spaces $X$ and $Y$ respectively.
We say that a polynomial map $\alpha \colon X \to Y$ \emph{preserves closure equivalence} if \[x \approx_{\group{G}} y \Rightarrow \alpha(x) \approx_{\group{H}} \alpha(y)\] holds for every $x, y \in X$.
Conversely, we say that $\alpha$ \emph{reflects closure equivalence} (or \emph{preserves closure inequivalence}) if the opposite implication \[\alpha(x) \approx_{\group{H}} \alpha(y)  \Rightarrow x \approx_{\group{G}} y\] holds for every $x, y \in X$.
\end{definition}

\begin{lemma}\label{lem:beta crit}
    Let $X$ and $Y$ be representations of groups $\group{G}$ and $\group{H}$ respectively, and let $\alpha \colon X \to Y$ be a polynomial map.
    Suppose that there exists a group homomorphism~$\beta\colon \group{G} \to \group{H}$ such that~$\alpha(\group{g} x) = \beta(\group{g}) \alpha(x)$ for all $\group{g} \in \group{G}$, $x\in X$.
    Then $\alpha$ preserves closure equivalence.
\end{lemma}

\begin{lemma}\label{thm:reflect}
    Let $X$ and $Y$ be representations of groups $\group{G}$ and $\group{H}$ respectively, with $\group{H}$ reductive.
    Suppose a polynomial map $\alpha \colon X \to Y$ preserves closure equivalence.
    The following~statements~are~equivalent:
    \begin{itemize}
        \item[(a)] $\alpha$ reflects closure equivalence;
        \item[(b)] for every separating set $\Gamma \subseteq \bbC[Y]^{\group{H}}$, the set \[\Gamma \circ \alpha = \{ F \circ \alpha \mid F \in \Gamma \} \subseteq \bbC[X]^{\group{G}}\] is separating;
        \item[(c)] the set $\{ F \circ \alpha \mid F \in \bbC[Y]^{\group{H}} \} \subseteq \bbC[X]^{\group{G}}$ is separating;
        \item[(d)] for some separating set $\Gamma \subseteq \bbC[Y]^{\group{H}}$, the set $\Gamma \circ \alpha$ is separating.
    \end{itemize}
\end{lemma}

\subsection{Tensor algebras and tensor contractions}\label{subsec:tensors}
\begin{definition}
    Let $V$ be a vector space. The space \[ \tspace{V}{a}{b} = V^{\otimes a} \otimes (V^*)^{\otimes b} \] is called the \emph{(mixed) tensor space of type $\tworow{a}{b}$ over $V$}.
\end{definition}

We define the tensor product on elementary tensors as
\begin{multline*}
    (\bigotimes_{i = 1}^{a_1} v_i \otimes \bigotimes_{j = 1}^{b_1} w_j) \otimes (\bigotimes_{i = 1}^{a_2} x_i \otimes \bigotimes_{j = 1}^{b_2} y_j) \\ = (\bigotimes_{i = 1}^{a_1} v_i \otimes \bigotimes_{i = 1}^{a_2} x_i) \otimes (\bigotimes_{j = 1}^{b_1} w_i \otimes \bigotimes_{j = 1}^{b_2} y_j)
\end{multline*}
where $v_i, x_i \in V$ and $w_j, y_j \in V^*$, and extend it bilinearly to arbitrary tensors.

\begin{definition}
    Let $V$ be a vector space.
    The \emph{(mixed) tensor algebra} over $V$ is the $\bbN \times \bbN$-graded algebra \[\mathcal{T}(V) = \bigoplus\limits_{\tworow{a}{b} \in \bbN \times \bbN} \tspace{V}{a}{b}\] with the tensor product operation $\otimes$ defined above.
\end{definition}

The action of $(\pi,\sigma) \in \Symg_a \times \Symg_b$ is given by
\begin{align}\label{eq:permutation action}
    (\pi, \sigma) \cdot (\bigotimes_{i = 1}^a v_i \otimes \bigotimes_{j = 1}^b w_j) = \bigotimes_{i = 1}^a v_{\pi^{-1}i} \otimes \bigotimes_{j = 1}^b w_{\sigma^{-1}j}.
\end{align}

\begin{definition}
    Let $V$ be a vector space.
    The \emph{identity tensor} $\Id \in \tspace{V}{1}{1} = V \otimes V^*$ is the tensor corresponding to the identity map $V \to V$.
\end{definition}

\begin{definition}
    Let $V$ be a vector space.
    For every $\tworow{a}{b} \in \bbN \times \bbN$ and $p \in [a]$, $q \in [b]$ the \emph{contraction map} $\Tr^{p:a}_{q:b} \colon \tspace{V}{a}{b} \to \tspace{V}{a-1}{b-1}$ \emph{contracting the $p$-th contravariant factor with the $q$-th covariant factor} is the linear map defined on elementary tensors as
    \[
        \Tr^{p:a}_{q:b} \left(\bigotimes_{i = 1}^a v_i \otimes \bigotimes_{j = 1}^b w_j\right) = w_q(v_p) \cdot \bigotimes_{i = 1, i \neq p}^a v_i \otimes \bigotimes_{j = 1, j \neq q}^b w_j.
    \]
    We write $\Tr^p_q$ if the tensor type $\tworow{a}{b}$ is clear from the context.
\end{definition}

\begin{definition}
A \emph{partial bijection} is a bijection $\gamma \colon P \to Q$ between subsets~$P \subseteq [a]$ and~$Q \subseteq [b]$.
Given such a partial bijection, we define
$\Tr_{\gamma} \colon \tspace{V}{a}{b} \to \tspace{V}{a-k}{b-k}$, where $k = \abs P = \abs Q$, as the contraction of all contravariant factors with indices in $P$ with the covariant factors with indices in~$Q$ according to the bijection $\gamma$, that is,
\[
    \Tr_{\gamma} (\bigotimes_{i = 1}^a v_i \otimes \bigotimes_{j = 1}^b w_j)
  = \prod_{p \in P} w_{\gamma(p)}(v_p) \cdot \left(\bigotimes_{i \notin P} v_i \otimes \bigotimes_{j \notin Q} w_j\right)
\]
We also write $\Tr^{p_1,\dots,p_k:a}_{q_1,\dots,q_k:b} := \Tr_\gamma$ when $P = \{p_1,\dots,p_k\}$, $Q = \{q_1,\dots,q_k\}$, $\gamma(p_j) = q_j$ for all~$j\in[k]$.
\end{definition}

The composition of linear maps induces a bilinear map $\tspace{V}{a}{b} \times \tspace{V}{b}{c} \to \tspace{V}{a}{c}$, which we denote by
\begin{align}\label{eq:tensor composition}
t \cdot s = \Tr^{a+1,\dots,a+b:a+b}_{\phantom{a+}1,\dots,\phantom{a+}b:b+c} (t \otimes s)
\end{align}
for $t \in \tspace{V}{a}{b}$, $s \in \tspace{V}{b}{c}$.

\begin{definition}[Tensor spaces and algebra]
    Let $\vtuple{V} = (V_1, \dots, V_m)$ be a tuple of vector spaces.
    The \emph{(mixed) tensor space of type~$\tworow{\ituple{a}}{\ituple{b}} \in \bbN^m \times \bbN^m$} over $\vtuple{V}$ is defined as
    \[
        \tspace{\vtuple{V}}{\ituple{a}}{\ituple{b}} = \bigotimes_{i = 1}^m \tspace{V_i}{a_i}{b_i} = \bigotimes_{i = 1}^m \left(V_i^{\otimes a_i} \otimes (V_i^*)^{\otimes b_i}\right).
    \]
    We abbreviate $\vtuple{V}^{\otimes\ituple{a}} = \bigotimes_{i = 1}^m V_i^{\otimes a_i}$.
    The \emph{(mixed) tensor algebra} over $\vtuple{V}$ is the $\bbN^m \times \bbN^m$-graded algebra
    \[ \mathcal{T}(\vtuple{V})
    = \bigotimes_{i = 1}^m \mathcal{T}(V_i)
    = \bigoplus_{\tworow{\ituple{a}}{\ituple{b}} \in \bbN^m \times \bbN^m} \tspace{\vtuple{V}}{\ituple{a}}{\ituple{b}}
    \]
    with the tensor product operation~$\ot$ inherited from the~$\mathcal{T}(V_i)$.
\end{definition}

For every $i \in [m]$, the tensor space $\tspace{\vtuple{V}}{\ituple{e_i}}{\ituple{e_i}} = V_i \otimes V_i^*$ contains a distinguished element corresponding to the identity map, which we call the \emph{identity tensor on~$V_i$} and denote by~$\Id[V_i]$.

\begin{definition}[Tensor tuple representation]\label{def:tens tup rep}
Let $\vtuple{V} = (V_1, \dots, V_n)$ be a tuple of vector spaces, and let $\group{G}$ be a reductive subgroup of $\GL(\vtuple{V})$.
A \emph{tensor tuple representation} of $\group{G}$ is a representation of the form $\rep{\bigoplus_{k = 1}^p \tspace{\vtuple{V}}{\ituple{a}_k}{\ituple{b}_k}}{\group{G}}$ for some tensor types $\tworow{\ituple{a}_1}{\ituple{b}_1}, \dots, \tworow{\ituple{a}_p}{\ituple{b}_p} \in \bbN^m \times \bbN^m$.
\end{definition}

\subsection{Tensor tuple sequences and the complexity class \OCIclass}\label{subsec:tuples}
\begin{definition}[Tensor tuple sequences]
Let $\tworow{\ituple{a}_1}{\ituple{b}_1}$, $\tworow{\ituple{a}_2}{\ituple{b}_2}$, $\dots$, $\tworow{\ituple{a}_p}{\ituple{b}_p} \in \bbN^m \times \bbN^m$.
The corresponding \emph{tensor tuple sequence} is the multivariate {$p$-sequence} $\rep{X_{\ituple{n}}}{\group{G}_{\ituple{n}}}$ where
$\group{G}_{\ituple{n}} = \prod_{i = 1}^m \GL_{n_i}$ and $X_{\ituple{n}} = \bigoplus_{k = 1}^p \tspace{(\bbC^{n_1}, \dots, \bbC^{n_m})}{\ituple{a}_k}{\ituple{b}_k}$, and $X_{\ituple{n}}$ is equipped with the standard basis as defined above.
When $p=1$, this is called a \emph{tensor sequence}.
We will also the convenient symbolic notation
\[ \rep{\bigoplus_{k = 1}^p \tspace{\vtuple{V}}{\ituple{a}_k}{\ituple{b}_k}}{\GL(\vtuple{V})}, \]
where we think of~$V_1, \dots, V_m$ as variables ranging over the coordinate vector spaces, and $\vtuple{V} = (V_1, \dots, V_m)$.

We also allow~$\group{G}_{\ituple{n}} \subset \prod_{i = 1}^m \GL_{n_i}$ to be a suitable subgroup and use analogous notation:
$\SL(\vtuple{V})$ corresponds to the group sequence $\prod_{i = 1}^{m} \SL_{n_i}$, $\Og(\vtuple{V})$~corresponds to $\prod_{i = 1}^{m} \Og_{n_i}$, and $\Sp(\vtuple{V})$ corresponds to $\prod_{i = 1}^{m} \Sp(n_i)$ (in the last case only even dimensions $n_i$ are used).
\end{definition}

\begin{definition}[\OCIclass]
    We define the complexity class $\OCIclass = \OCIclass_\GL$ as the class of computational problems that are reducible (by a polynomial-time Karp reduction) to any orbit closure intersection problem for a tensor tuple sequence $\rep{\bigoplus_{k = 1}^p \tspace{\vtuple{V}}{\ituple{a}_k}{\ituple{b}_k}}{\GL(\vtuple{V})}$, where $p \in \bbN$ and $\tworow{\ituple{a}_1}{\ituple{b}_1}, \dots, \tworow{\ituple{a}_p}{\ituple{b}_p} \in \bbN^m {\times} \bbN^m$ for some $m\in\bbN$.

    The classes $\OCIclass_\Og$ and $\OCIclass_\Sp$ are defined analogously using tensor tuple sequences of the form
    $\rep{\bigoplus_{k = 1}^p \vtuple{V}^{\otimes \ituple{a}_k}}{\Og(\vtuple{V})}$ and
    $\rep{\bigoplus_{k = 1}^p \vtuple{V}^{\otimes \ituple{a}_k}}{\Sp(\vtuple{V})}$ respectively.
\end{definition}

\subsection{Invariant theory of tensors tuple representations}\label{subsec:tensor invariants}
\begin{definition}[Balancedness]
    A tensor space over $\vtuple{V}$ is \emph{balanced} if it has the form $\tspace{\vtuple{V}}{\ituple{c}}{\ituple{c}}$.
    Elements of a balanced tensor space are called \emph{balanced tensors}.
    A tensor tuple representation is called \emph{balanced} if all its summands are balanced, that is, if it has the form $\bigoplus_{i = 1}^{p} \tspace{\vtuple{V}}{\ituple{c}_k}{\ituple{c}_k}$.
\end{definition}

\begin{theorem}\label{thm:contraction-invariants-multiple}
    Let $\vtuple{V} = (V_1, \dots, V_m)$ be vector spaces, let $\group{G}_i$ be reductive subgroups of $\GL(V_i)$, and let~$\ituple{a}_1,\ldots,\ituple{b}_p \in \bbN^m$.
    Consider the tensor tuple representation of $\group{G} = \prod_{i = 1}^m \group{G}_i$ on $X = \bigoplus_{k = 1}^p \tspace{\vtuple{V}}{\ituple{a}_k}{\ituple{b}_k}$.
    Let $h_{i1}, \dots, h_{ir_i}$ denote homogeneous generators of $\mathcal{T}(V_i)^{\group{G_i}}$.
    Then the invariant algebra $\bbC[X]^{\group{G}}$ is linearly spanned by invariants of the form
    {\small
    \begin{equation}\label{eq:contraction-invariant-multiple}
        F(x_1, \dots, x_p) \\= \bigotimes_{i = 1}^m \Tr_{\pi_i} \left(\bigotimes_{k = 1}^p x_k^{\otimes d_k} \otimes \bigotimes_{i = 1}^m \bigotimes_{\ell = 1}^{r_i} h_{i\ell}^{\otimes f_{i\ell}}\right)
    \end{equation}}where the tensor in brackets is balanced and $\pi_1, \dots, \pi_m$ are permutations of appropriate sizes.
\end{theorem}

\begin{definition}
  Let $V$ be a vector space and let $\group{G}$ be a reductive subgroup of $\GL(V)$.
  If $\mathcal{T}(V)^{\group{G}} = \left<h_1, \dots, h_r\right>_{\Tr}$, with homogeneous~$h_k \in \tspace{V}{u_k}{v_k}$, then we call $h_1, \dots, h_k$ \emph{tensor invariant generators} for $\group{G}$.

  The invariants of the form~\eqref{eq:contraction-invariant-multiple} are called \emph{contraction invariants} for the tensor tuple representation $\rep{\bigoplus_{k = 1}^p \tspace{\vtuple{V}}{\ituple{a}_k}{\ituple{b}_k}}{\group{G}}$.
\end{definition}

\subsection{Reductions and completeness for products of general linear groups}\label{subsec:gl}
\begin{lemma}\label{lem:GL-balanced-to-sum}
    Let $\ituple{c}_1,\dots,\ituple{c}_q$ and $\ituple{c} \in \bbN^m$ with $\ituple{c} \geq \ituple{c_\ell}$ for all~$\ell$ (where~$\geq$ is co\-ord\-i\-nate-wise inequality).
    Then there is an efficient algebraic reduction from~$\rep{\bigoplus_{\ell = 1}^{q}\tspace{\vtuple{V}}{\ituple{c_\ell}}{\ituple{c_\ell}}}{\GL(\vtuple{V})}$ to~$\rep{\left(\tspace{\vtuple{V}}{\ituple{c}}{\ituple{c}}\right)^{\oplus q}}{\GL(\vtuple{V})}$.
\end{lemma}

\begin{theorem}\label{thm:complete X}
The orbit closure intersection problems for the following tensor tuple sequences are complete for $\OCIclass$:
    \begin{enumerate}
        \item $\rep{\left(X^{\otimes 2} \otimes (X^*)^{\otimes 2}\right) \oplus \left(X \otimes X^*\right)^{\oplus 2}}{\GL(X)}$
        \item $\rep{\left(X^{\otimes 2} \otimes (X^*)^{\otimes 2}\right)^{\oplus 2}}{\GL(X)}$
    \end{enumerate}
\end{theorem}

\begin{lemma}\label{lem:GL-sum-to-one}
    If $p \leq d!$, then there exists an efficient algebraic reduction from $\rep{(\tspace{X}{c}{c})^{\oplus p}}{\GL(X)}$ to $\rep{\tspace{X}{c + d}{c + d}}{\GL(X)}$.
\end{lemma}

\subsection{Reductions and completeness for orthogonal and symplectic groups}\label{subsec:o sp}
\begin{theorem}\label{thm:O-to-GL}
    For every $\ituple{a}_1, \dots, \ituple{a}_p \in \bbN^m$, there exists an efficient algebraic reduction from
    $\rep{\bigoplus_{k = 1}^p \vtuple{V}^{\otimes \ituple{a}_p}}{\Og(\vtuple{V})}$
    to $\rep{\bigoplus_{k = 1}^p \vtuple{V}^{\otimes \ituple{a}_p} \oplus \bigoplus_{i = 1}^m (V_i^*)^{\otimes 2}}{\GL(\vtuple{V})}$.
\end{theorem}

\begin{theorem}\label{thm:GL-to-O}
    Let $\tworow{\ituple{a}_1}{\ituple{b}_1}, \dots, \tworow{\ituple{a}_p}{\ituple{b}_p} \in \bbN^{m} \times \bbN^{m}$ and define~$\ituple{c}_k = \ituple{a}_k + \ituple{b}_k$.
    Then there is an efficient algebraic reduction from $\rep{\bigoplus_{k = 1}^p \tspace{\vtuple{V}}{\ituple{a}_k}{\ituple{b}_k}}{\GL(\vtuple{V})}$ to $\rep{\bigoplus_{k = 1}^p \vtuple{W}^{\otimes \ituple{c}_k}}{\Og(\vtuple{W})}$.
\end{theorem}


